'faq'=>[
['cat'=>'नयाँ दर्ता','q'=>[['को आवेदन दिन सक्छ र दर्ता कसरी हुन्छ?','तपाईं अनलाइन सुरु गर्नुहुन्छ, त्यसपछि नियुक्तिको दिन छानिएको कार्यालयमा भौतिक प्रमाणीकरण र बायोमेट्रिक दर्ताका लागि जानुहुन्छ।'],['प्रक्रिया कति समय लाग्छ?','यो प्रोटोटाइपले स्थिति हेर्नुहोस् समयरेखामा प्रत्येक चरण देखाउँछ। वास्तविक समय विभागले तोक्छ।']]],
['cat'=>'आवश्यक कागजात','q'=>[['परिचयपत्र दर्ताका लागि कुन कागजात चाहिन्छ?','नेपाली नागरिकता प्रमाणपत्रको सक्कल आवश्यक छ। अवस्थाअनुसार बसाइँसराइ प्रमाणपत्र, विवाह वा नाता प्रमाणीकरण, वा जन्म मिति पुष्टि गर्ने आधिकारिक कागजात पनि चाहिन सक्छ।']]],
['cat'=>'नियुक्ति','q'=>[['के ल्याउनु पर्छ र कहिले पुग्नु पर्छ?','सक्कल कागजात र नियुक्तिको पुष्टि ल्याउनुहोस्, र तोकिएको समयभन्दा अगावै पुग्नुहोस्।']]],
['cat'=>'परिचयपत्र स्थिति','q'=>[['आवेदनको स्थिति कसरी हेर्ने?','आवेदन नम्बर र जन्म मिति राखेर स्थिति हेर्नुहोस् प्रयोग गर्नुहोस्।']]],
['cat'=>'प्रतिस्थापन','q'=>[['प्रतिस्थापन कहिले चाहिन्छ र कति शुल्क लाग्छ?','कार्ड हराएमा वा बिग्रिएमा प्रतिलिपि माग्न सकिन्छ। यस प्रोटोटाइपमा शुल्क रु. ५०० हो, जुन नक्कली भुक्तानीबाट तिरिन्छ।']]],
['cat'=>'सामान्य प्रश्न','q'=>[['कुन बायोमेट्रिक जानकारी सङ्कलन गरिन्छ?','फोटो, औँठाछाप, आइरिस र विद्युतीय हस्ताक्षर दर्ता कार्यालयमा प्रत्यक्ष रूपमा सङ्कलन गरिन्छ, अनलाइन कहिल्यै होइन।'],['के यो आधिकारिक परिचयपत्र पोर्टल हो?','होइन। यो नक्कली टोकन, डेमो OTP र नक्कली भुक्तानी भएको शैक्षिक प्रोटोटाइप हो।']]]]];
